using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

namespace Fs.Tests;

/// <summary>
/// BannedSymbols.txt is generated by Fs.Analyzers/tools/GenBannedSymbols.cs. These tests re-derive, with Roslyn's own documentation-comment IDs (not the
/// generator's reflection code), what the plan's rule bans (section 10.4, card T0.4), and run the real BannedApiAnalyzers over snippets.
/// A failing completeness test after a runtime upgrade means: regenerate the file (the command is in the generator's header).
/// </summary>
[TestClass]
public sealed class BannedSymbolsTests
{
    private static readonly string[] AllowedMath = ["Abs", "Sqrt", "Floor", "Ceiling", "Truncate", "CopySign", "Min", "Max"];

    private static readonly string[] NamedBanned =
    [
        "Acos","Acosh","AcosPi","Asin","Asinh","AsinPi","Atan","Atanh","AtanPi","Atan2","Atan2Pi","Cbrt","Cos","CosPi","Cosh","Exp","Exp2","Exp10",
        "ExpM1","Exp2M1","Exp10M1","FusedMultiplyAdd","Hypot","ILogB","Ieee754Remainder","Log","Log2","Log10","LogP1","Log2P1","Log10P1","Pow","ReciprocalEstimate",
        "ReciprocalSqrtEstimate","RootN","Round","ScaleB","Sin","SinCos","SinPi","Sinh","Tan","TanPi","Tanh","MultiplyAddEstimate","BitIncrement","BitDecrement",
    ];

    private static readonly Lazy<(HashSet<string> Entries, string Text)> s_file = new(() =>
    {
        var text = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "BannedSymbols.txt"));
        var entries = text.Split('\n')
            .Where(l => l.Length > 0 && l[0] != '#')
            .Select(l => l.Split(';')[0])
            .ToHashSet(StringComparer.Ordinal);
        return (entries, text);
    });

    private static readonly Lazy<CSharpCompilation> s_compilation = new(() => RoslynHost.Compile("class X {}"));

    private static IEnumerable<IMethodSymbol> PublicStaticMethods(string metadataName) =>
        s_compilation.Value.GetTypeByMetadataName(metadataName)!
            .GetMembers().OfType<IMethodSymbol>()
            .Where(m => m.DeclaredAccessibility == Accessibility.Public && m.IsStatic && m.MethodKind == MethodKind.Ordinary);

    private static bool HasFloatParameter(IMethodSymbol m) =>
        m.Parameters.Any(p => p.Type.SpecialType is SpecialType.System_Double or SpecialType.System_Single || p.Type.Name == "Half");

    [TestMethod]
    public void EveryMathAndMathFMethodOutsideTheAllowedListIsBanned()
    {
        var missing = new List<string>();
        var wronglyBanned = new List<string>();
        foreach (var type in new[] { "System.Math", "System.MathF" })
            foreach (var m in PublicStaticMethods(type))
            {
                var id = m.GetDocumentationCommentId()!;
                bool expected = m.Name == "Round" || (!AllowedMath.Contains(m.Name) && HasFloatParameter(m));
                bool present = s_file.Value.Entries.Contains(id);
                if (expected && !present) missing.Add(id);
                if (!expected && present) wronglyBanned.Add(id);
            }

        CollectionAssert.AreEqual(Array.Empty<string>(), missing, "not banned, but should be: regenerate BannedSymbols.txt");
        CollectionAssert.AreEqual(Array.Empty<string>(), wronglyBanned, "banned, but allowed by the plan (Abs Sqrt Floor Ceiling Truncate CopySign Min Max)");
    }

    [TestMethod]
    public void TheAllowedMathFunctionsAreNotBannedAndRoundIsBannedInEveryOverload()
    {
        var entries = s_file.Value.Entries;

        foreach (var name in AllowedMath)
            Assert.IsFalse(entries.Any(e => e.StartsWith($"M:System.Math.{name}(") || e.StartsWith($"M:System.MathF.{name}(")), $"{name} must stay allowed");
        Assert.HasCount(8, entries.Where(e => e.StartsWith("M:System.Math.Round(")).ToArray(), "Math.Round has eight overloads (double, decimal; digits; midpoint)");
    }

    [TestMethod]
    public void DoubleSingleHalfAndTheVectorTypesAreBannedByName()
    {
        var missing = new List<string>();
        foreach (var type in new[] { "System.Double", "System.Single", "System.Half" })
            foreach (var m in PublicStaticMethods(type).Where(m => NamedBanned.Contains(m.Name) || m.Name.EndsWith("Native")))
                if (!s_file.Value.Entries.Contains(m.GetDocumentationCommentId()!)) missing.Add(m.GetDocumentationCommentId()!);

        var vectorNames = NamedBanned.Concat(["Sum", "Dot"]).ToArray();
        foreach (var type in new[] { "System.Runtime.Intrinsics.Vector64", "System.Runtime.Intrinsics.Vector128", "System.Runtime.Intrinsics.Vector256", "System.Runtime.Intrinsics.Vector512" })
            foreach (var m in PublicStaticMethods(type).Where(m => vectorNames.Contains(m.Name) || m.Name.EndsWith("Native")))
                if (!s_file.Value.Entries.Contains(m.GetDocumentationCommentId()!)) missing.Add(m.GetDocumentationCommentId()!);

        CollectionAssert.AreEqual(Array.Empty<string>(), missing, "not banned, but should be: regenerate BannedSymbols.txt");
    }

    [TestMethod]
    public void TheNamedTypesAreBanned()
    {
        string[] required =
        [
            "T:System.Numerics.Tensors.TensorPrimitives", "N:System.Numerics.Tensors", "T:System.Numerics.Vector`1", "T:System.Numerics.Vector",
            "T:System.Numerics.IExponentialFunctions`1", "T:System.Numerics.ILogarithmicFunctions`1", "T:System.Numerics.IPowerFunctions`1",
            "T:System.Numerics.IRootFunctions`1", "T:System.Numerics.ITrigonometricFunctions`1", "T:System.Numerics.IHyperbolicFunctions`1",
        ];

        foreach (var id in required) Assert.IsTrue(s_file.Value.Entries.Contains(id), id);
    }

    // ---- the real BannedApiAnalyzers, run over snippets, with this file as its AdditionalFile ----

    private static async Task<string[]> Rs0030Async(string body)
    {
        var compilation = RoslynHost.Compile($$"""
            using System;
            using System.Numerics;
            using System.Numerics.Tensors;
            using System.Runtime.Intrinsics;
            class C
            {
                void M(double d, float f, double[] a, Vector128<float> v, Vector128<double> vd)
                {
                    {{body}}
                }
            }
            """);
        CollectionAssert.AreEqual(Array.Empty<string>(), RoslynHost.CompilerErrors(compilation), "the snippet must compile");
        var dll = Path.Combine(AppContext.BaseDirectory, "banned-api-analyzers", "Microsoft.CodeAnalysis.CSharp.BannedApiAnalyzers.dll");
        var analyzers = RoslynHost.LoadCSharpAnalyzers(dll);
        Assert.IsFalse(analyzers.IsDefaultOrEmpty, "BannedApiAnalyzers must load");
        var diagnostics = await RoslynHost.AnalyzeAsync(compilation, analyzers, new RoslynHost.TextFile("BannedSymbols.txt", s_file.Value.Text));
        return diagnostics.Where(x => x.Id == "RS0030").Select(x => x.GetMessage()).ToArray();
    }

    [TestMethod]
    [DataRow("var x = Math.Exp(d);", "Math.Exp(double)")]
    [DataRow("var x = Math.Sin(d);", "Math.Sin(double)")]
    [DataRow("var x = Math.Pow(d, d);", "Math.Pow(double, double)")]
    [DataRow("var x = double.Hypot(d, d);", "double.Hypot(double, double)")]
    [DataRow("var x = Math.Round(d);", "Math.Round(double)")]
    [DataRow("var x = Math.Round(d, MidpointRounding.AwayFromZero);", "Math.Round(double, MidpointRounding)")]
    [DataRow("var x = Math.FusedMultiplyAdd(d, d, d);", "Math.FusedMultiplyAdd")]
    [DataRow("var x = Math.Cbrt(d);", "Math.Cbrt(double)")]
    [DataRow("var x = Math.Atan2(d, d);", "Math.Atan2(double, double)")]
    [DataRow("var x = Math.Log(d);", "Math.Log(double)")]
    [DataRow("var x = Math.Sign(d);", "Math.Sign(double)")]
    [DataRow("var x = MathF.Cos(f);", "MathF.Cos(float)")]
    [DataRow("var x = double.Exp(d);", "double.Exp(double)")]
    [DataRow("var x = float.Sin(f);", "float.Sin(float)")]
    [DataRow("var x = TensorPrimitives.Sum(a);", "TensorPrimitives")]
    [DataRow("var x = new Vector<float>();", "Vector<T>")]
    [DataRow("var x = Vector.IsHardwareAccelerated;", "Vector")]
    [DataRow("var x = Vector128.Sum(v);", "Vector128.Sum<T>(Vector128<T>)")]
    [DataRow("var x = Vector128.Dot(v, v);", "Vector128.Dot<T>(Vector128<T>, Vector128<T>)")]
    [DataRow("var x = Vector128.MaxNative(v, v);", "Vector128.MaxNative<T>(Vector128<T>, Vector128<T>)")]
    [DataRow("var x = Vector128.MultiplyAddEstimate(vd, vd, vd);", "Vector128.MultiplyAddEstimate")]
    [DataRow("var x = Vector128.ConvertToInt32Native(v);", "Vector128.ConvertToInt32Native")]
    public async Task BanApiReportsTheBannedCall(string body, string symbolPart)
    {
        var messages = await Rs0030Async(body);

        Assert.IsGreaterThanOrEqualTo(1, messages.Length, "expected RS0030");
        Assert.IsTrue(messages.Any(m => m.Contains(symbolPart)), string.Join(Environment.NewLine, messages));
    }

    [TestMethod]
    [DataRow("var x = Math.Abs(d);")]
    [DataRow("var x = Math.Sqrt(d);")]
    [DataRow("var x = Math.Floor(d);")]
    [DataRow("var x = Math.Ceiling(d);")]
    [DataRow("var x = Math.Truncate(d);")]
    [DataRow("var x = Math.CopySign(d, -1.0);")]
    [DataRow("var x = Math.Min(d, 1.0) + Math.Max(d, 1.0);")]
    [DataRow("var x = MathF.Sqrt(f) + MathF.Abs(f) + MathF.Min(f, 1f);")]
    [DataRow("var x = Math.Max(1, 2) + Math.Abs(-3) + Math.Min(4L, 5L);")]
    [DataRow("var x = Math.PI + Math.E;")]
    [DataRow("var x = Vector128.Create(1f) + Vector128.Create(2f);")]
    [DataRow("var x = Vector128.Floor(vd) + Vector128.Sqrt(vd);")]
    [DataRow("var x = double.Sqrt(d) + double.Abs(d);")]
    public async Task BanApiAllowsTheAllowedCalls(string body)
    {
        var messages = await Rs0030Async(body);

        CollectionAssert.AreEqual(Array.Empty<string>(), messages);
    }
}
